{

"kind": "propose",
"summary": "Increase probe timeouts to match application startup duration",
"hypotheses": [
    {
        "root_cause_class": "probe_too_strict_for_startup",
        "summary": "Probes timeout before application completes startup",
        "supporting": ["probe_kills", "probe_timeouts", "ev-container_logs_tail"],
        "contradicting": ["killed_during_startup", "crashed_on_its_own"],
        "missing": ["revision_health"],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "shop",
        "name": "search-api",
        "uid": "uid-deployment-search-api"
    },
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 5
        },
        "readiness": {
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Allow probes to wait for application startup completion",
    "rationale": "Logs show application responds to /ready and /healthz within 5 seconds, but current 1s timeout causes failures. Increasing to 5s aligns with observed startup duration.",
    "cited_evidence_ids": ["ev-container_logs_tail", "ev-rollout_history", "ev-target_events"],
    "cited_predicates": ["probe_kills", "probe_timeouts", "killed_during_startup"]
}
}
